package com.goodsbuy.app.data.db

import java.io.File
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Guards the most common schema-evolution mistake: changing the indices on an
 * entity (which changes the exported schema) without updating the migration.
 *
 * The exported `2.json` is generated by Room from [com.goodsbuy.app.data.entity.CollectibleEntity],
 * so comparing it against the hand-written [MIGRATION_1_2_INDICES] list catches drift.
 */
class SchemaMigrationConsistencyTest {

    private val schemaDir = sequenceOf(
        File("schemas/com.goodsbuy.app.data.db.AppDatabase"),
        File("app/schemas/com.goodsbuy.app.data.db.AppDatabase")
    ).first { it.isDirectory }

    @Test
    fun `version 1 schema has no indices`() {
        assertTrue("1.json should declare no indices", exportedIndices("1.json").isEmpty())
    }

    @Test
    fun `migration indices match the exported version 2 schema`() {
        val exported = exportedIndices("2.json").toSet()
        val migrated = MIGRATION_1_2_INDICES.map { IndexSpec(it.name, it.column) }.toSet()

        assertEquals(migrated, exported)
    }

    @Test
    fun `exported schema version matches the database version`() {
        val json = Json.parseToJsonElement(File(schemaDir, "2.json").readText()).jsonObject
        val version = json["database"]!!.jsonObject["version"]!!.jsonPrimitive.content.toInt()
        assertEquals(2, version)
    }

    private fun exportedIndices(fileName: String): List<IndexSpec> {
        val json = Json.parseToJsonElement(File(schemaDir, fileName).readText()).jsonObject
        val entities = json["database"]!!.jsonObject["entities"]!!.jsonArray
        return entities.flatMap { entity ->
            entity.jsonObject["indices"]!!.jsonArray.map { index ->
                val obj = index.jsonObject
                IndexSpec(
                    name = obj["name"]!!.jsonPrimitive.content,
                    column = obj["columnNames"]!!.jsonArray.first().jsonPrimitive.content
                )
            }
        }
    }
}
